use nepl3_core::{budget::*, schema::*, source::*, view::*};
use nepl3_grammar_core::compile::{
    self, NamedClass,
    package::{CompiledLanguage, PackageContext},
};

fn budget() -> Budget {
    Budget::new(Limits {
        source_bytes: 10_000_000,
        work: 100_000_000,
        depth: 1000,
        nodes: 1_000_000,
        allocation_units: 500_000_000,
        output_bytes: 10_000_000,
        diagnostics: 1000,
        events: 1000,
    })
}
fn load(path:&str)->Result<nepl3_grammar_core::model::Document,String>{ let bytes=match path{"conformance/fixtures/grammar/region/priority.neplg" => include_bytes!("C:/projects/NEPL3-runtime/.tmp/independent-region-fixed/seeds/priority.json").as_slice(),"conformance/fixtures/grammar/region/view.neplg" => include_bytes!("C:/projects/NEPL3-runtime/.tmp/independent-region-fixed/seeds/view.json").as_slice(),"conformance/fixtures/grammar/binding/execution.neplg" => include_bytes!("C:/projects/NEPL3-runtime/.tmp/independent-region-fixed/seeds/execution.json").as_slice(),_=>return Err("unlisted fixed seed".into())};nepl3_tools::bootstrap::load(bytes,&mut budget(),&mut SourceAdmission::default()).map_err(|e|format!("{e:?}"))}
fn compile(path: &str) -> Result<Result<CompiledLanguage, compile::CompileError>, String> {
    eprintln!("helper load start");
    let doc = load(path)?;
    eprintln!("helper load done");
    let mut b = budget();
    let checked = doc
        .validate(&mut b, &mut SourceAdmission::default())
        .map_err(|e| format!("{e:?}"))?;
    let mut registry = SchemaRegistry::default();
    eprintln!("helper descriptors start");
    for descriptor in [
        nepl3_core::schema::foundation::descriptor(&mut b),
        nepl3_reader::schema::descriptor(&mut b),
        nepl3_engine::schema::descriptor(&mut b),
    ] {
        eprintln!("helper descriptor returned");
        let descriptor = descriptor.map_err(|e| format!("{e:?}"))?;
        let schema = descriptor.reference(&mut b).map_err(|e| format!("{e:?}"))?;
        registry
            .register(schema, descriptor, &mut b)
            .map_err(|e| format!("{e:?}"))?;
    }
    registry.finalize(&mut b).map_err(|e| format!("{e:?}"))?;
    let schema = registry
        .selected("nepl3.foundation", 1)
        .ok_or("foundation")?
        .clone();
    let classes = [
        ("content", FallbackRole::Content),
        ("marker", FallbackRole::Marker),
        ("name", FallbackRole::Name),
        ("quantity", FallbackRole::Quantity),
    ]
    .into_iter()
    .map(|(n, f)| NamedClass {
        name: n.into(),
        class: PresentationClass {
            schema: schema.clone(),
            name: n.into(),
            fallback: f,
        },
    })
    .collect::<Vec<_>>();
    Ok(compile::package::compile(
        &checked,
        &PackageContext {
            package: "test.surface",
            state_type: &TypeDescriptor::Unit,
            reader_imports: &[],
            extensions: &[],
            classes: &classes,
            views: &[],
        },
        registry,
        &mut b,
    ))
}

