    ) -> Result<T, String>,
) -> Result<T, String> {
    with_completed_input(compiled, input, |parsed, profile, b, a| {
        let checked = parsed.tree().validate(profile, b, a).map_err(err)?;
        finish(&checked, profile, b, a)
