let bundle=&parsed.tree().bundle;let mut forged=parsed.reader_facts().to_vec();let batch=forged.iter_mut().find(|batch|batch.node.is_some_and(|node|bundle.nodes[node.0 as usize].token.is_some_and(|token|bundle.tokens[token.0 as usize].head.start()==5))).ok_or("first Word batch")?;
